import{a as e,c as t,i as n,t as r}from"./app-C4mzCnKe.js";var i=JSON.parse(`{"path":"/risks.html","title":"风险与反模式（来自已踩过的坑）","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"risks.md"}`),a={name:`risks.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="风险与反模式-来自已踩过的坑" tabindex="-1"><a class="header-anchor" href="#风险与反模式-来自已踩过的坑"><span>风险与反模式（来自已踩过的坑）</span></a></h1><table><thead><tr><th>反模式</th><th>后果</th><th>对策</th></tr></thead><tbody><tr><td>判决器与选手共模</td><td>&quot;测试全过但决策没用&quot;</td><td>物理隔离 + 只读 + 独立样本定义</td></tr><tr><td>用交易笔数当样本</td><td>自由度虚高、t 值假显著</td><td>以日为样本，配对对齐日期</td></tr><tr><td>未剔 beta 就报超额</td><td>把 beta 当 alpha</td><td>超额对沪深300剔 beta，配同天随机对照</td></tr><tr><td>数据口径漂移</td><td>前复权 vs 涨跌停价、元/万元、东财 vs 同花顺混用</td><td>口径契约 + QC 门禁</td></tr><tr><td>为一点风险否决全部 / 为一点机会否决卖出</td><td>错失机会或错过离场</td><td>概率权重判断，判决器输出概率而非二元</td></tr><tr><td>主控越权直接写生产</td><td>规划层污染生产数据</td><td>主控只规划整合，写域由 ACL 强约束</td></tr><tr><td>用模型自评当奖励（Reward Hacking）</td><td>自进化朝错误方向狂奔</td><td>奖励 = 可机器验证的真实结果（T+N 超额 / 配对 vs 随机对照），判决器先行</td></tr><tr><td>评估器自己在 good/bad 间来回翻</td><td>判决器噪声，回滚误判</td><td>标签 token 的 logprobs 判置信度，低置信升级精判 / 人工复核</td></tr><tr><td>把「时间顺序」当「因果来源」</td><td>归因归到刚好相邻的错误节点</td><td>沿溯源图依赖边做多步结构归因（信用传播），用图距离而非时间间隔</td></tr><tr><td>进化污染判决器</td><td>重蹈「测试全过但决策没用」</td><td>冻结层（判决器/口径/回测引擎）与可进化层分离；进化只发生在可进化层</td></tr><tr><td>span 缺失 / 口径不合法</td><td>归因无据、回放失败</td><td>前缀白名单门禁 + 采集层机械拦截（进不了判决器）</td></tr><tr><td>指标被全样本稀释（未分层）</td><td>假结论（如 9 信号都不 beat 随机篮）</td><td>定向观测按 regime 圈选切片再下结论</td></tr></tbody></table>`,2)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};